const plannedAvailable=round(income-plannedCharges-plannedSavings),actualImpact=round(overBudgetSpend+unbudgetedSpend),available=round(plannedAvailable-actualImpact),remainingEnvelopeTotal=round([...variableEnvelopes.entries()].reduce((s,[c,n])=>s+Math.max(0,n-(used.get(c)||0)),0)),remainingPlannedChargeTotal=round([...plannedByCategory.entries()].reduce((s,[c,n])=>s+Math.max(0,n-(used.get(c)||0)),0));
